
const DHD = {
  money(n){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0)},
  get(key, fallback=[]){try{return JSON.parse(localStorage.getItem('dhd_'+key)) ?? fallback}catch(e){return fallback}},
  set(key,value){localStorage.setItem('dhd_'+key,JSON.stringify(value))},
  toast(msg){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)},
  saveDesign(data){let all=this.get('designs',[]);all.unshift({...data,id:(Date.now()+Math.floor(Math.random()*1000)),savedAt:new Date().toLocaleString()});this.set('designs',all);this.toast('Your dream design has been saved!')},
  img(name){return name}
};
