function header(){return `<div class="topbar"><div class="wrap nav"><a class="brand" href="index.html">dream<span>haus.</span></a><nav class="navlinks"><a href="index.html">Home</a><a href="houses.html">House Designs</a><a href="customize.html">Customize</a><a href="furniture.html">Furniture</a><a href="budget.html">Budget</a><a href="saved.html">My Designs <span id="saved-count"></span></a><a href="login.html" class="btn btn-primary" style="padding:10px 15px">Sign in</a></nav></div></div>`}
function footer(){return `<footer class="footer"><div class="wrap footer-inner"><div><a class="brand" style="color:#fff" href="index.html">dream<span>haus.</span></a><p>Imagine it. Design it. Make it yours.<br>Plan your dream home one choice at a time.</p></div><div><strong>Explore</strong><p><a href="houses.html">House designs</a><br><a href="rooms.html">Room inspiration</a><br><a href="budget.html">Budget planner</a></p></div><div><strong>Project note</strong><p>Demo project for home design planning.<br>Prices are estimates, not quotations.</p></div></div></footer><div id="toast" class="toast"></div>`}
function shell(content){document.getElementById('app').innerHTML=header()+content+footer();let n=DHD.get('designs',[]).length;let sc=document.getElementById('saved-count');if(sc)sc.textContent=n?`(${n})`:''}
function houseCard(h){return `<article class="card"><div class="card-img"><img src="${h.img}" alt="${h.name}" onerror="this.onerror=null;this.src='https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=900&q=80'"></div><div class="card-body"><span class="tag">${h.type} · ${h.bhk}</span><h3 style="margin-top:12px">${h.name}</h3><p>${h.desc}</p><div class="mini-row"><span class="price">From ${DHD.money(h.price)}</span><button class="primary" onclick="chooseHouse('${h.id}')">Customize →</button></div></div></article>`}
function productCard(p){return `<article class="card"><div class="card-img"><img src="${p.img}" alt="${p.name}" onerror="this.style.display='none'"></div><div class="card-body"><span class="tag">${p.room}</span><h3 style="margin-top:10px">${p.name}</h3><div class="mini-row"><span class="price">${DHD.money(p.price)}</span><button class="primary" onclick="addItem('${p.id}')">＋ Add</button></div></div></article>`}
function chooseHouse(id){DHD.set('selectedHouse',houses.find(h=>h.id===id)||houses[0]);location.href='customize.html'}
function addItem(id){let p=products.find(x=>x.id===id);let list=DHD.get('selectedItems',[]);if(!list.some(x=>x.id===id))list.push(p);DHD.set('selectedItems',list);DHD.toast(p.name+' added to your plan')}
function previewMarkup(house, colour, items, cls='dream-preview'){
 const tint={'Warm White':'#f4efe4','Sage Green':'#b8c9b4','Dusty Blue':'#9eafc0','Terracotta':'#c78367','Soft Beige':'#d7c6a7'}[colour]||'#f4efe4';
 const chosen=(items||[]).slice(0,6);
 return `<div class="${cls}" style="--wall-tint:${tint}"><img class="dream-preview-bg" src="${house.img}" alt="${house.name} preview"><div class="dream-preview-tint"></div><div class="dream-preview-label"><strong>${house.name}</strong><span>${colour||'Warm White'} walls</span></div><div class="dream-preview-items">${chosen.map(p=>`<div class="dream-item"><img src="${p.img}" alt="${p.name}"><span>${p.name}</span></div>`).join('')}${!chosen.length?'<div class="dream-item empty-item">Choose furniture to see it here</div>':''}</div></div>`;
}
function home(){shell(`<main><section class="hero wrap"><div class="hero-grid"><div><div class="eyebrow">Your vision, thoughtfully designed</div><h1>A home that feels like <em style="color:var(--green)">you.</em></h1><p class="lead">Dream it from the first brick to the final cushion. Explore house styles, personalize rooms, choose furniture and keep your estimated budget in one beautiful place.</p><div class="actions"><a class="btn btn-primary" href="houses.html">Explore house designs ↗</a><a class="btn btn-light" href="customize.html">Start designing</a></div><div class="stats"><div class="stat"><strong>25+</strong><span>Design pages to explore</span></div><div class="stat"><strong>6</strong><span>House styles</span></div><div class="stat"><strong>₹</strong><span>Budget planning tools</span></div></div></div><div class="hero-image"><img src="https://images.unsplash.com/photo-1600595466949-7f3f6c6d5e5a?auto=format&fit=crop&w=1200&q=85" alt="Beautiful modern dream house" onerror="this.src='https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=85'"><div class="floating-note"><span class="eyebrow">Start with a feeling</span><strong>Make room for your dreams.</strong><span class="small">A few choices can shape your whole home.</span></div></div></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow">Find your style</div><h2>Homes to fall in love with</h2></div><a class="btn btn-light" href="houses.html">View all designs →</a></div><div class="grid">${houses.slice(0,3).map(houseCard).join('')}</div></section><section class="section wrap"><div class="banner"><div><div class="eyebrow" style="color:#e4c58f">Your home, your choices</div><h2>Every little detail matters.</h2><p>Pick rooms, explore furniture, choose colours and build a plan that matches your taste and budget.</p></div><a class="btn btn-gold" href="customize.html">Customize my home →</a></div></section><section class="section wrap"><div class="section-head"><div><div class="eyebrow">A simple process</div><h2>From idea to plan</h2></div></div><div class="grid"><div class="card"><div class="card-body"><span class="tag">01 · Explore</span><h3>Choose a house style</h3><p>Browse modern, traditional, duplex and villa ideas.</p></div></div><div class="card"><div class="card-body"><span class="tag">02 · Personalize</span><h3>Make it your own</h3><p>Select rooms, colours and furniture you love.</p></div></div><div class="card"><div class="card-body"><span class="tag">03 · Plan</span><h3>Understand your budget</h3><p>Review estimated costs and save your design.</p></div></div></div></section></main>`)}
function housesPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">The starting point</div><h1 style="font-size:54px">Find your kind of home.</h1><p>Explore a curated collection of house concepts. Choose one to start personalizing your dream home.</p><div class="filters" id="house-filters"><button class="active light" data-filter="All">All styles</button><button class="light" data-filter="Modern">Modern</button><button class="light" data-filter="Traditional">Traditional</button><button class="light" data-filter="Luxury">Luxury</button><button class="light" data-filter="Duplex">Duplex</button><button class="light" data-filter="Budget">Budget-friendly</button></div></section><div class="grid" id="house-grid">${houses.map(houseCard).join('')}</div><section class="section"><div class="notice">Planning note: all house costs shown here are sample estimates for this demo. Real construction costs depend on location, built-up area, materials, labour and local approvals.</div></section></main>`);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('house-grid').innerHTML=houses.filter(h=>b.dataset.filter==='All'||h.type===b.dataset.filter).map(houseCard).join('')})}
function customizePage(){let chosen=DHD.get('selectedHouse',houses[0]);let items=DHD.get('selectedItems',[]);let latest=DHD.get('latestPlan',{});let startColour=latest.colour||'Warm White';shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Make it personal</div><h1 style="font-size:54px">Customize your home.</h1><p>Choose a house, wall colour and furniture. The live preview updates as you make choices.</p></section><div class="grid two"><section class="form-card"><h3>01 · House details</h3><div class="field"><label for="houseType">House style</label><select id="houseType">${houses.map(h=>`<option value="${h.id}" ${chosen.id===h.id?'selected':''}>${h.name}</option>`).join('')}</select></div><div class="field"><label for="bhk">House size</label><select id="bhk">${['1 BHK','2 BHK','3 BHK','4 BHK','Custom size'].map(v=>`<option ${((latest.bhk||chosen.bhk)==v)?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>02 · Pick your main wall colour</label><div class="color-options"><button type="button" class="color-choice ${startColour==='Warm White'?'selected':''}" data-color="Warm White" style="background:#f4efe4" aria-label="Warm White"></button><button type="button" class="color-choice ${startColour==='Sage Green'?'selected':''}" data-color="Sage Green" style="background:#b8c9b4" aria-label="Sage Green"></button><button type="button" class="color-choice ${startColour==='Dusty Blue'?'selected':''}" data-color="Dusty Blue" style="background:#9eafc0" aria-label="Dusty Blue"></button><button type="button" class="color-choice ${startColour==='Terracotta'?'selected':''}" data-color="Terracotta" style="background:#c78367" aria-label="Terracotta"></button><button type="button" class="color-choice ${startColour==='Soft Beige'?'selected':''}" data-color="Soft Beige" style="background:#d7c6a7" aria-label="Soft Beige"></button></div><p class="small" id="selected-color">Selected: ${startColour}</p></div><div class="field"><label>03 · Choose your add-ons</label><label class="check-row"><input type="checkbox" value="garden" data-extra="50000"> Garden landscape — ₹50,000</label><label class="check-row"><input type="checkbox" value="pool" data-extra="250000"> Swimming pool — ₹2,50,000</label><label class="check-row"><input type="checkbox" value="solar" data-extra="80000"> Solar panel setup — ₹80,000</label><label class="check-row"><input type="checkbox" value="smart" data-extra="45000"> Smart home starter — ₹45,000</label></div><div class="field"><label for="notes">Your special ideas (optional)</label><textarea id="notes" rows="3" placeholder="e.g. lots of sunlight, reading corner..."></textarea></div><button class="primary" id="save-custom">Save my dream design →</button></section><section><div id="live-preview">${previewMarkup(chosen,startColour,items)}</div><div class="summary" style="margin-top:18px"><h3>Your design summary</h3><div class="summary-line"><span>House</span><strong id="sum-house">${chosen.name}</strong></div><div class="summary-line"><span>Base estimate</span><strong id="sum-base">${DHD.money(chosen.price)}</strong></div><div class="summary-line"><span>Add-ons</span><strong id="sum-extras">₹0</strong></div><div class="summary-line"><span>Furniture selected</span><strong id="sum-furniture">${items.length} items</strong></div><div class="summary-line"><span>Estimated total</span><strong id="sum-total">${DHD.money(chosen.price+items.reduce((s,i)=>s+i.price,0))}</strong></div><p class="small">Preview is a visual concept: selected furniture thumbnails are shown with your house choice.</p><a class="btn btn-light" href="furniture.html" style="margin-top:8px">Choose furniture →</a></div></section></div></main>`);let colour=startColour;let house=chosen;function renderPreview(){document.getElementById('live-preview').innerHTML=previewMarkup(house,colour,DHD.get('selectedItems',[]))}function update(){let extras=[...document.querySelectorAll('[data-extra]:checked')].reduce((s,x)=>s+Number(x.dataset.extra),0);let list=DHD.get('selectedItems',[]);document.getElementById('sum-house').textContent=house.name;document.getElementById('sum-base').textContent=DHD.money(house.price);document.getElementById('sum-extras').textContent=DHD.money(extras);document.getElementById('sum-furniture').textContent=list.length+' items';document.getElementById('sum-total').textContent=DHD.money(house.price+extras+list.reduce((s,i)=>s+i.price,0));renderPreview();return {extras,list,total:house.price+extras+list.reduce((s,i)=>s+i.price,0)}}document.getElementById('houseType').onchange=e=>{house=houses.find(h=>h.id===e.target.value);update()};document.querySelectorAll('.color-choice').forEach(b=>b.onclick=()=>{document.querySelectorAll('.color-choice').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');colour=b.dataset.color;document.getElementById('selected-color').textContent='Selected: '+colour;update()});document.querySelectorAll('[data-extra]').forEach(x=>x.onchange=update);document.getElementById('save-custom').onclick=()=>{let d=update();let savedItems=d.list.map(x=>({id:x.id,name:x.name,price:x.price,img:x.img,room:x.room}));DHD.saveDesign({house:house.name,houseId:house.id,houseImg:house.img,bhk:document.getElementById('bhk').value,colour,extras:[...document.querySelectorAll('[data-extra]:checked')].map(x=>x.parentElement.textContent.trim()),items:savedItems,total:d.total,notes:document.getElementById('notes').value});DHD.set('selectedHouse',house);DHD.set('latestPlan',{house:house.name,houseId:house.id,houseImg:house.img,bhk:document.getElementById('bhk').value,colour,total:d.total,extras:d.extras,items:savedItems});DHD.toast('Design and preview saved!')};update()}
function furniturePage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">The finishing touches</div><h1 style="font-size:54px">Choose the pieces you love.</h1><p>Add furniture, lighting and home features to your plan. Your selected items contribute to the estimated total.</p><div class="filters" id="product-filters"><button class="active light" data-cat="All">All items</button><button class="light" data-cat="Furniture">Furniture</button><button class="light" data-cat="Interior">Interior</button><button class="light" data-cat="Lighting">Lighting</button><button class="light" data-cat="Outdoor">Outdoor</button></div></section><div class="notice" style="margin-bottom:22px">Choose Add to include an item in your design. Selections are stored in this browser for the demo.</div><div class="grid" id="product-grid">${products.map(productCard).join('')}</div><section class="section"><div class="banner"><div><h2>Your home is taking shape.</h2><p>When you are ready, review your budget and save your design.</p></div><a class="btn btn-gold" href="budget.html">Review budget →</a></div></section></main>`);document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-cat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('product-grid').innerHTML=products.filter(p=>b.dataset.cat==='All'||p.cat===b.dataset.cat).map(productCard).join('')})}
function budgetPage(){let house=DHD.get('selectedHouse',houses[0]),items=DHD.get('selectedItems',[]),latest=DHD.get('latestPlan',{});shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Plan with confidence</div><h1 style="font-size:54px">Your budget, at a glance.</h1><p>Build an approximate cost plan from your house choice, selected furniture and optional categories. Change the values to explore different budgets.</p></section><div class="grid two"><section class="form-card"><h3>Cost planner</h3><div class="field"><label for="construction">House construction estimate (₹)</label><input id="construction" type="number" min="1000000" max="50000000" step="10000" required value="${Math.max(1000000,house.price)}"></div><div class="field"><label for="interior">Interior & flooring (₹)</label><input id="interior" type="number" min="10000" max="10000000" step="1000" required value="200000"></div><div class="field"><label for="furniture-cost">Furniture selected (₹)</label><input id="furniture-cost" type="number" min="0" max="5000000" step="1000" value="${items.reduce((s,i)=>s+i.price,0)}"></div><div class="field"><label for="electrical">Electrical & lighting (₹)</label><input id="electrical" type="number" min="5000" max="2500000" step="1000" required value="50000"></div><div class="field"><label for="outdoor">Garden / outdoor (₹)</label><input id="outdoor" type="number" min="0" max="5000000" step="1000" value="50000"></div><div class="field"><label for="extra">Other expenses (₹)</label><input id="extra" type="number" min="0" max="5000000" step="1000" value="25000"></div><div class="field"><label for="contingency">Extra buffer (%)</label><input id="contingency" type="number" min="0" max="30" step="1" value="10"></div><button class="primary" id="calc">Calculate total ↗</button> <button class="light" id="save-budget">Save budget</button></section><section><div class="summary"><span class="eyebrow">Estimated project budget</span><h2 id="grand-total" style="font-size:48px;margin-top:12px">${DHD.money(0)}</h2><p class="small">Includes the extra buffer amount.</p><div id="budget-breakdown"></div></div><div class="notice" style="margin-top:18px">Important: this is a learning/demo calculator, not a professional construction quote. Actual prices vary by location, area, material quality, labour and approvals.</div><div class="card" style="margin-top:18px"><div class="card-body"><h3>Want to personalize the plan?</h3><p>Return to the designer to choose a house style, wall colour and add-ons.</p><a class="btn btn-light" href="customize.html">Customize house →</a></div></div></section></div></main>`);function calculate(){let limits={construction:{min:1000000,max:50000000,label:'House construction'},interior:{min:10000,max:10000000,label:'Interior & flooring'},'furniture-cost':{min:0,max:5000000,label:'Furniture'},electrical:{min:5000,max:2500000,label:'Electrical & lighting'},outdoor:{min:0,max:5000000,label:'Garden / outdoor'},extra:{min:0,max:5000000,label:'Other expenses'}};let fields=Object.keys(limits);for(let id of fields){let el=document.getElementById(id),v=el.value.trim(),n=Number(v),lim=limits[id];if(v===''||!Number.isFinite(n)||n<lim.min||n>lim.max){DHD.toast(lim.label+': enter ₹'+lim.min.toLocaleString('en-IN')+' to ₹'+lim.max.toLocaleString('en-IN'));el.focus();return null}}let pctInput=document.getElementById('contingency'),pct=Number(pctInput.value);if(pctInput.value.trim()===''||!Number.isFinite(pct)||pct<0||pct>30){DHD.toast('Extra buffer must be between 0% and 30%');pctInput.focus();return null}let values=fields.map(id=>Number(document.getElementById(id).value));let sub=values.reduce((a,b)=>a+b,0),buffer=sub*pct/100,total=sub+buffer;document.getElementById('grand-total').textContent=DHD.money(total);document.getElementById('budget-breakdown').innerHTML=fields.map((id,i)=>`<div class="summary-line"><span>${({'construction':'Construction','interior':'Interior & flooring','furniture-cost':'Furniture','electrical':'Electrical & lighting','outdoor':'Garden / outdoor','extra':'Other expenses'})[id]}</span><strong>${DHD.money(values[i])}</strong></div>`).join('')+`<div class="summary-line"><span>Buffer (${pct}%)</span><strong>${DHD.money(buffer)}</strong></div><div class="summary-line"><span>Total</span><strong>${DHD.money(total)}</strong></div>`;return {values,sub,pct,buffer,total}}document.getElementById('calc').onclick=calculate;document.getElementById('save-budget').onclick=()=>{let b=calculate();if(!b)return;let all=DHD.get('budgets',[]);all.unshift({...b,date:new Date().toLocaleString()});DHD.set('budgets',all);DHD.toast('Budget saved! Open My Designs in the top menu to view it.')};calculate()}
function savedPage(){let designs=DHD.get('designs',[]),budgets=DHD.get('budgets',[]);shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Your personal collection</div><h1 style="font-size:54px">My saved designs.</h1><p>Your saved house preview, colour, selected furniture and estimated budget appear here.</p></section><div class="section-head"><div><h2>Saved home plans</h2><p class="small">You have ${designs.length} saved design${designs.length===1?'':'s'}.</p></div><a class="btn btn-primary" href="customize.html">＋ New design</a></div>${designs.length?`<div class="grid">${designs.map(d=>{let catalogHouse=houses.find(x=>x.id===d.houseId)||houses[0];let h={...catalogHouse,name:d.house||catalogHouse.name,img:d.houseImg||catalogHouse.img};return `<article class="card">${previewMarkup(h,d.colour||'Warm White',Array.isArray(d.items)?d.items.map(x=>typeof x==='string'?{name:x,img:''}:x):[],'dream-preview saved-preview')}<div class="card-body"><span class="tag">${d.savedAt||'Saved plan'}</span><h3 style="margin-top:12px">${d.house||'Dream House'}</h3><p>${d.bhk||''} · ${d.colour||'Colour not selected'}</p><div class="summary-line"><span>Selected items</span><strong>${(d.items||[]).length}</strong></div><div class="summary-line"><span>Estimated total</span><strong>${DHD.money(d.total)}</strong></div><p class="small">${(d.extras||[]).join(', ')}</p><button class="light" onclick="removeDesign(${d.id})">Delete plan</button></div></article>`}).join('')}</div>`:`<div class="empty"><h3>No saved designs yet</h3><p>Start customizing your house and click “Save my dream design”.</p><a class="btn btn-primary" href="customize.html">Start designing →</a></div>`}<section class="section"><h2>Saved budgets</h2>${budgets.length?`<div class="card"><div class="card-body">${budgets.slice(0,10).map((b,i)=>`<div class="summary-line"><span>Budget ${budgets.length-i} · ${b.date||''}</span><strong>${DHD.money(b.total)}</strong></div>`).join('')}</div></div>`:`<p class="small">No budgets saved yet. Calculate a budget and choose Save budget.</p>`}</section><div class="notice">Saved designs and budgets are shown on this page. If they do not appear, use the same browser and VS Code Live Server each time.</div></main>`)}
function removeDesign(id){DHD.set('designs',DHD.get('designs',[]).filter(d=>d.id!==id));savedPage();DHD.toast('Design deleted')}
function loginPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Welcome home</div><h1 style="font-size:54px">Your design space.</h1><p>This is a front-end demo sign-in screen for presentation. It does not create a secure account or verify a real password.</p></section><div class="grid two"><div class="form-card"><h3>Sign in / Create demo profile</h3><div class="field"><label for="username">Your name</label><input id="username" placeholder="Enter your name"></div><div class="field"><label for="email">Email address</label><input id="email" type="email" placeholder="you@example.com"></div><button class="primary" id="login">Continue to my dashboard →</button><p class="small">For a real account system, a server-side backend and database are required.</p></div><div class="summary"><div class="eyebrow">Your home journey</div><h2>Everything starts with an idea.</h2><p>Save a design, track a budget and come back to your home plan whenever you need.</p><a class="btn btn-light" href="saved.html">View saved designs</a></div></div></main>`);document.getElementById('login').onclick=()=>{let n=document.getElementById('username').value.trim(),e=document.getElementById('email').value.trim();if(!n||!e||!e.includes('@')){DHD.toast('Enter your name and a valid email');return}DHD.set('profile',{name:n,email:e});location.href='dashboard.html'}}
function dashboardPage(){let p=DHD.get('profile',null),ds=DHD.get('designs',[]),bs=DHD.get('budgets',[]);shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Your home hub</div><h1 style="font-size:54px">Hello${p?' '+p.name:''}.</h1><p>Welcome to your personal dream-home dashboard.</p></section><div class="stats"><div class="stat"><strong>${ds.length}</strong><span>Saved designs</span></div><div class="stat"><strong>${bs.length}</strong><span>Saved budgets</span></div><div class="stat"><strong>${p?'✓':'—'}</strong><span>Demo profile</span></div></div><section class="section"><div class="grid"><div class="card"><div class="card-body"><h3>Design a house</h3><p>Choose your house type, colours and special features.</p><a class="btn btn-primary" href="customize.html">Start design</a></div></div><div class="card"><div class="card-body"><h3>Plan a budget</h3><p>Estimate costs and save the budget plan.</p><a class="btn btn-primary" href="budget.html">Open calculator</a></div></div><div class="card"><div class="card-body"><h3>View saved work</h3><p>Review your saved home plans and budgets.</p><a class="btn btn-primary" href="saved.html">My designs</a></div></div></div></section></main>`)}
function galleryPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Ideas worth keeping</div><h1 style="font-size:54px">Inspiration gallery.</h1><p>Explore a few room styles and find details that feel right for your future home.</p></section><div class="grid">${[{name:'Sunlit Living Room',room:'Living Room',img:products[0].img,desc:'Comfortable seating and warm natural tones.'},{name:'Quiet Bedroom',room:'Bedroom',img:products[2].img,desc:'Soft textures for a restful atmosphere.'},{name:'Modern Kitchen',room:'Kitchen',img:products[5].img,desc:'A clean layout with useful storage.'},{name:'Garden Escape',room:'Outdoor',img:products[8].img,desc:'A green corner to slow down.'},{name:'Warm Lighting',room:'Lighting',img:products[6].img,desc:'Lighting that makes a room feel inviting.'},{name:'Bathroom Retreat',room:'Bathroom',img:products[10].img,desc:'Simple details and a calm palette.'}].map(x=>`<article class="card"><div class="card-img"><img src="${x.img}" alt="${x.name}"></div><div class="card-body"><span class="tag">${x.room}</span><h3 style="margin-top:10px">${x.name}</h3><p>${x.desc}</p><a class="btn btn-light" href="customize.html">Use this inspiration →</a></div></article>`).join('')}</div></main>`)}
function genericPage(title,sub,items){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Dreamhaus collection</div><h1 style="font-size:54px">${title}</h1><p>${sub}</p></section><div class="grid">${items.map((x,i)=>`<article class="card"><div class="card-img"><img src="${x.img||products[i%products.length].img}" alt="${x.name}" onerror="this.style.display='none'"></div><div class="card-body"><span class="tag">${x.tag||'Inspiration'}</span><h3 style="margin-top:10px">${x.name}</h3><p>${x.desc||'Explore styles, colours and details for your dream home.'}</p><a class="btn btn-light" href="${x.link||'customize.html'}">Explore →</a></div></article>`).join('')}</div></main>`)}
function contactPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">We would love to hear from you</div><h1 style="font-size:54px">Let's talk homes.</h1><p>Share your feedback or tell us what feature would make your home planning easier.</p></section><div class="grid two"><form class="form-card" id="contact-form"><div class="field"><label for="cname">Name</label><input id="cname" required></div><div class="field"><label for="cemail">Email</label><input id="cemail" type="email" required></div><div class="field"><label for="topic">Topic</label><select id="topic"><option>Website feedback</option><option>House design idea</option><option>Budget planner</option><option>Other</option></select></div><div class="field"><label for="message">Message</label><textarea id="message" rows="4" required></textarea></div><button class="primary">Save feedback</button></form><div class="summary"><h2>Made for your ideas.</h2><p>Use this demo form to save feedback locally in your browser.</p><p class="small">This sample website does not send messages to a server.</p></div></div></main>`);document.getElementById('contact-form').onsubmit=e=>{e.preventDefault();let a=DHD.get('feedback',[]);a.push({name:document.getElementById('cname').value,email:document.getElementById('cemail').value,topic:document.getElementById('topic').value,message:document.getElementById('message').value,date:new Date().toLocaleString()});DHD.set('feedback',a);e.target.reset();DHD.toast('Thank you! Feedback saved in this browser.')}}
function adminPage(){let feedback=DHD.get('feedback',[]),ds=DHD.get('designs',[]);shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Project overview</div><h1 style="font-size:54px">Admin dashboard.</h1><p>A simple demonstration dashboard showing data saved by this browser. This is not protected by a real admin login.</p></section><div class="stats"><div class="stat"><strong>${houses.length}</strong><span>House concepts</span></div><div class="stat"><strong>${products.length}</strong><span>Furniture & home items</span></div><div class="stat"><strong>${ds.length}</strong><span>Saved designs on device</span></div></div><section class="section"><h2>House catalog</h2><div class="card"><div class="card-body">${houses.map(h=>`<div class="summary-line"><span>${h.name} · ${h.type}</span><strong>${DHD.money(h.price)}</strong></div>`).join('')}</div></div></section><section class="section"><h2>Feedback received on this device</h2>${feedback.length?`<div class="card"><div class="card-body">${feedback.map(f=>`<div class="summary-line"><span><strong>${f.name}</strong><br><small>${f.topic} · ${f.date}</small><br>${f.message}</span><span>${f.email}</span></div>`).join('')}</div></div>`:'<p class="small">No feedback submitted yet.</p>'}</section></main>`)}
function faqPage(){genericPage('Frequently asked questions','A quick guide to using the Dream House Designer demo.',[{name:'Can I save my design?',desc:'Yes. Use Save my dream design. It is stored in your current browser.',tag:'Saving'},{name:'Are the prices exact?',desc:'No. All listed prices are sample estimates for demonstration only.',tag:'Budget'},{name:'Can I change colours?',desc:'Open Customize and select one of the colour swatches.',tag:'Design'},{name:'Does it use an online database?',desc:'This fast demo stores data in browser localStorage. A PHP/MySQL backend can be added later.',tag:'Technology'},{name:'Can I use it on mobile?',desc:'Yes. The layout is responsive and designed to fit phones and laptops.',tag:'Access'},{name:'How do I compare ideas?',desc:'Save more than one plan and review them on My Saved Designs.',tag:'Planning'}])}
function aboutPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">About the project</div><h1 style="font-size:54px">A little more than a mood board.</h1><p>Dream House Designer is a home-planning website concept that brings house inspiration, personal choices and budget estimation into one place.</p></section><div class="grid two"><div class="room-preview"><img src="https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1000&q=80" alt="Modern house"></div><div><h2>Designed around your choices.</h2><p class="lead">The goal is to help users explore different home styles, select furniture and features, estimate a budget and save their favourite plans.</p><p class="lead">The current version is a front-end demonstration built with HTML, CSS and JavaScript. Saved plans use browser storage. A server database can be connected in a future version.</p><a class="btn btn-primary" href="houses.html">Explore designs →</a></div></div></main>`)}
function roomsPage(){genericPage('Explore room by room','Small choices make a home feel personal. Browse room inspiration and continue customizing.',[{name:'Living Room',img:products[0].img,desc:'Comfortable spaces for family and guests.',tag:'Common area'},{name:'Bedroom',img:products[2].img,desc:'A restful space with personal touches.',tag:'Private space'},{name:'Kitchen',img:products[5].img,desc:'Useful storage and easy movement.',tag:'Cooking'},{name:'Dining Room',img:products[4].img,desc:'A welcoming place to gather.',tag:'Togetherness'},{name:'Bathroom',img:products[10].img,desc:'Practical, clean and calming.',tag:'Essentials'},{name:'Garden',img:products[8].img,desc:'A green outdoor corner.',tag:'Outdoor'}])}
function stylePage(){genericPage('Choose your design style','Find the look that suits your taste.',[{name:'Modern Minimal',img:houses[0].img,desc:'Simple forms, open spaces and clean details.',tag:'Modern'},{name:'Traditional Warmth',img:houses[2].img,desc:'Timeless materials and familiar comfort.',tag:'Traditional'},{name:'Luxury Living',img:houses[1].img,desc:'Elegant finishes and spacious design.',tag:'Luxury'},{name:'Smart Budget',img:houses[4].img,desc:'Practical choices with style and comfort.',tag:'Budget'},{name:'Contemporary Duplex',img:houses[3].img,desc:'A smart layout over two levels.',tag:'Duplex'},{name:'Coastal Calm',img:houses[5].img,desc:'Natural light and a relaxed palette.',tag:'Coastal'}])}
function coloursPage(){genericPage('Colour studio','Explore a palette for your walls and interiors. Use the Customize page to select a colour for your plan.',[{name:'Warm White',img:'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=900&q=80',desc:'Bright, simple and timeless.',tag:'#F4EFE4'},{name:'Sage Green',img:'https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=900&q=80',desc:'Soft, earthy and peaceful.',tag:'#B8C9B4'},{name:'Dusty Blue',img:'https://images.unsplash.com/photo-1616486029423-aaa4789e8c9a?auto=format&fit=crop&w=900&q=80',desc:'Cool, gentle and elegant.',tag:'#9EAFC0'},{name:'Terracotta',img:'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=900&q=80',desc:'Warm and full of character.',tag:'#C78367'},{name:'Soft Beige',img:'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=900&q=80',desc:'Natural and welcoming.',tag:'#D7C6A7'},{name:'Forest Green',img:'https://images.unsplash.com/photo-1616486029423-aaa4789e8c9a?auto=format&fit=crop&w=900&q=80',desc:'Deep and grounding.',tag:'#315B45'}])}
function flooringPage(){genericPage('Flooring ideas','Choose a finish that balances look, comfort and maintenance.',[{name:'Wood-look Flooring',desc:'A warm finish for bedrooms and living spaces.',tag:'Warm'},{name:'Large Format Tiles',desc:'A clean, spacious look with fewer grout lines.',tag:'Modern'},{name:'Natural Stone',desc:'Unique textures and an earthy feel.',tag:'Classic'},{name:'Patterned Tiles',desc:'A statement finish for selected areas.',tag:'Creative'}])}
function lightingPage(){genericPage('Lighting studio','Layer ambient, task and accent lighting for a welcoming home.',[{name:'Pendant Lights',img:products[6].img,desc:'A focal point above dining or seating areas.',tag:'Accent'},{name:'Warm Ceiling Lights',desc:'Soft general light for everyday comfort.',tag:'Ambient'},{name:'Bedside Lamps',desc:'Gentle light for reading and winding down.',tag:'Task'},{name:'Garden Lighting',img:products[8].img,desc:'Make paths and outdoor spaces feel inviting.',tag:'Outdoor'}])}
function doorsPage(){genericPage('Doors & windows','Explore practical and beautiful details for your home.',[{name:'Wooden Main Door',desc:'A warm welcome with a classic finish.',tag:'Entry'},{name:'Wide Sliding Windows',desc:'Bring daylight into the room.',tag:'Windows'},{name:'Glass Balcony Door',desc:'Connect the interior with outdoor views.',tag:'Balcony'},{name:'Minimal Interior Doors',desc:'A clean style that suits modern rooms.',tag:'Interior'}])}
function gardenPage(){genericPage('Garden & outdoor','Create an outdoor corner that fits your home and maintenance needs.',[{name:'Green Lawn',img:products[8].img,desc:'Open green space for relaxing.',tag:'Garden'},{name:'Flower Border',desc:'Add seasonal colour along a pathway.',tag:'Flowers'},{name:'Compact Pool',img:products[9].img,desc:'A pool concept for a larger outdoor area.',tag:'Pool'},{name:'Terrace Garden',desc:'Pots, planters and greenery on the terrace.',tag:'Terrace'}])}
function constructionPage(){genericPage('Construction planning','A starting point for thinking about the big pieces of a home project.',[{name:'Foundation & Structure',desc:'The core structure needs a qualified local professional.',tag:'Core'},{name:'Walls & Roofing',desc:'Plan materials and weather protection.',tag:'Shell'},{name:'Electrical & Plumbing',desc:'Include safe, professionally planned services.',tag:'Services'},{name:'Finishes',desc:'Flooring, paint, doors and final details.',tag:'Finishing'}])}
function comparePage(){let ds=DHD.get('designs',[]);shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Compare your favourites</div><h1 style="font-size:54px">Two ideas, side by side.</h1><p>Save a few plans first, then compare their house style, colour and estimated cost here.</p></section>${ds.length>=2?`<div class="grid two">${ds.slice(0,2).map(d=>`<div class="summary"><span class="tag">${d.bhk||'Home plan'}</span><h2 style="margin-top:15px">${d.house}</h2><p>Colour: ${d.colour||'Not selected'}</p><div class="summary-line"><span>Selected items</span><strong>${(d.items||[]).length}</strong></div><div class="summary-line"><span>Estimated total</span><strong>${DHD.money(d.total)}</strong></div></div>`).join('')}</div>`:`<div class="empty"><h3>Save at least two designs to compare</h3><p>Make different choices in Customize and save each plan.</p><a class="btn btn-primary" href="customize.html">Create a design</a></div>`}</main>`)}
function checklistPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Keep the plan organized</div><h1 style="font-size:54px">Home planning checklist.</h1><p>Tick off the items as you work through your dream-home plan. Your checklist is saved in this browser.</p></section><div class="form-card" id="checklist">${['Decide the house style and size','List must-have rooms','Set an initial budget','Choose wall colour palette','Select essential furniture','Plan lighting and electrical needs','Consider garden or outdoor space','Review estimated costs','Save the final design','Discuss real construction details with a qualified professional'].map((x,i)=>`<label class="check-row"><input type="checkbox" data-task="${i}"> ${x}</label>`).join('')}<div class="mini-row"><span id="check-progress">0 of 10 completed</span><button class="light" id="reset-check">Reset checklist</button></div></div></main>`);let vals=DHD.get('checklist',[]);document.querySelectorAll('[data-task]').forEach(c=>{c.checked=vals.includes(Number(c.dataset.task));c.onchange=()=>{let v=[...document.querySelectorAll('[data-task]:checked')].map(x=>Number(x.dataset.task));DHD.set('checklist',v);document.getElementById('check-progress').textContent=v.length+' of 10 completed'}});document.getElementById('check-progress').textContent=vals.length+' of 10 completed';document.getElementById('reset-check').onclick=()=>{DHD.set('checklist',[]);document.querySelectorAll('[data-task]').forEach(c=>c.checked=false);document.getElementById('check-progress').textContent='0 of 10 completed'}}
function inspirationPage(){genericPage('Small-space inspiration','Smart ideas for making every corner work harder.',[{name:'Entryway Storage',desc:'Use hooks, shelves and a compact bench.',tag:'Storage'},{name:'Multi-purpose Furniture',desc:'Choose pieces that offer more than one function.',tag:'Furniture'},{name:'Light Colour Palette',desc:'Use a consistent palette to keep rooms connected.',tag:'Colour'},{name:'Vertical Greenery',desc:'Bring plants into a small footprint.',tag:'Plants'}])}
function budgetTips(){genericPage('Budget planning tips','Use these simple planning reminders alongside the calculator.',[{name:'Set priorities first',desc:'Separate must-haves from nice-to-haves.',tag:'01'},{name:'Keep a contingency',desc:'Set aside a buffer for unexpected changes.',tag:'02'},{name:'Compare quotations',desc:'Request itemized quotes from qualified local professionals.',tag:'03'},{name:'Track every choice',desc:'Record selected materials and furniture prices.',tag:'04'},{name:'Recheck measurements',desc:'Area and dimensions have a major effect on costs.',tag:'05'},{name:'Review regularly',desc:'Update estimates when prices or choices change.',tag:'06'}])}
function profilePage(){let p=DHD.get('profile',{});shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Your details</div><h1 style="font-size:54px">My profile.</h1><p>Demo profile information stored in this browser.</p></section><div class="form-card"><div class="field"><label for="pname">Name</label><input id="pname" value="${p.name||''}"></div><div class="field"><label for="pemail">Email</label><input id="pemail" type="email" value="${p.email||''}"></div><button class="primary" id="save-profile">Save profile</button><a class="btn btn-light" href="dashboard.html">Dashboard</a></div></main>`);document.getElementById('save-profile').onclick=()=>{DHD.set('profile',{name:document.getElementById('pname').value,email:document.getElementById('pemail').value});DHD.toast('Profile saved')}}
function materialsPage(){genericPage('Materials explorer','Learn about common home finish categories before making selections.',[{name:'Wood',desc:'Used for doors, furniture and warm interior details.',tag:'Natural'},{name:'Ceramic & Porcelain',desc:'Common tile options for floors and walls.',tag:'Tile'},{name:'Glass',desc:'Can help bring light into selected spaces.',tag:'Light'},{name:'Stone',desc:'A durable natural finish with varied textures.',tag:'Texture'},{name:'Paint',desc:'A flexible way to add colour and refresh a room.',tag:'Colour'},{name:'Metal',desc:'Used in fixtures, railings and furniture details.',tag:'Detail'}])}
function helpPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Help centre</div><h1 style="font-size:54px">Need a hand?</h1><p>Use these quick steps to navigate the demo.</p></section><div class="grid two"><div class="card"><div class="card-body"><h3>1. Pick a house</h3><p>Open House Designs and click Customize on a design.</p></div></div><div class="card"><div class="card-body"><h3>2. Add items</h3><p>Open Furniture and click Add on the products you like.</p></div></div><div class="card"><div class="card-body"><h3>3. Calculate budget</h3><p>Open Budget, adjust amounts and press Calculate total.</p></div></div><div class="card"><div class="card-body"><h3>4. Save your plan</h3><p>Use Save my dream design or Save budget, then view My Designs.</p></div></div></div><section class="section"><div class="notice">Note: this demo stores information locally in the current browser. It is not an online multi-user database. Use the same browser and device to view saved data.</div></section></main>`)}
function wishlistPage(){let items=DHD.get('selectedItems',[]);shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Your favourite pieces</div><h1 style="font-size:54px">Selected furniture.</h1><p>Review the items you have added to your current plan.</p></section>${items.length?`<div class="grid">${items.map(p=>`<article class="card"><div class="card-img"><img src="${p.img}" alt="${p.name}"></div><div class="card-body"><h3>${p.name}</h3><div class="mini-row"><strong class="price">${DHD.money(p.price)}</strong><button class="light" onclick="removeItem('${p.id}')">Remove</button></div></div></article>`).join('')}</div><section class="section"><div class="summary"><div class="summary-line"><span>Items total</span><strong>${DHD.money(items.reduce((s,p)=>s+p.price,0))}</strong></div><a class="btn btn-primary" href="budget.html">Calculate full budget →</a></div></section>`:`<div class="empty"><h3>No items selected</h3><p>Browse the furniture store and add pieces to your plan.</p><a class="btn btn-primary" href="furniture.html">Browse furniture →</a></div>`}</main>`)}
function removeItem(id){DHD.set('selectedItems',DHD.get('selectedItems',[]).filter(p=>p.id!==id));wishlistPage()}
function reportPage(){let ds=DHD.get('designs',[]),bs=DHD.get('budgets',[]);shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Your project snapshot</div><h1 style="font-size:54px">Design report.</h1><p>A quick overview of the plans and budgets saved on this browser.</p></section><div class="summary"><div class="summary-line"><span>Saved designs</span><strong>${ds.length}</strong></div><div class="summary-line"><span>Saved budgets</span><strong>${bs.length}</strong></div><div class="summary-line"><span>Current furniture items</span><strong>${DHD.get('selectedItems',[]).length}</strong></div></div><section class="section"><button class="primary" onclick="window.print()">Print / Save as PDF</button> <a class="btn btn-light" href="saved.html">View saved designs</a></section></main>`)}
function styleGuidePage(){genericPage('Home style guide','Quick visual directions for common house design styles.',[{name:'Minimal',desc:'Less clutter, simple furniture and purposeful storage.',tag:'Style'},{name:'Scandinavian',desc:'Light woods, soft neutrals and useful forms.',tag:'Style'},{name:'Industrial',desc:'Metal accents, textured finishes and honest materials.',tag:'Style'},{name:'Traditional',desc:'Classic proportions and warm details.',tag:'Style'},{name:'Contemporary',desc:'Current shapes and balanced materials.',tag:'Style'},{name:'Nature-inspired',desc:'Greenery, natural textures and daylight.',tag:'Style'}])}
function maintenancePage(){genericPage('Home care planner','A simple reminder list for keeping a home in good shape.',[{name:'Monthly',desc:'Check taps, drains and common fittings.',tag:'Monthly'},{name:'Seasonal',desc:'Inspect roof drainage and outdoor areas.',tag:'Seasonal'},{name:'Yearly',desc:'Review electrical and plumbing needs with professionals.',tag:'Yearly'},{name:'Garden',desc:'Plan watering and plant care for your climate.',tag:'Outdoor'}])}
function termsPage(){shell(`<main class="wrap"><section class="pagehead"><div class="eyebrow">Please read</div><h1 style="font-size:54px">Demo terms & notes.</h1><p>This website is an educational project demonstration.</p></section><div class="form-card"><h3>Estimates</h3><p>All costs and examples are illustrative only and should not be treated as actual construction quotations.</p><h3>Saved information</h3><p>Selections are stored locally in your browser. This demo does not transmit them to a server.</p><h3>Account form</h3><p>The sign-in form is a demonstration only; it is not a secure authentication system.</p><h3>Images</h3><p>Images are loaded from external image URLs, so an internet connection is needed for the full visual experience.</p></div></main>`)}
function init(){switch(page){case'home':home();break;case'houses':housesPage();break;case'customize':customizePage();break;case'furniture':furniturePage();break;case'budget':budgetPage();break;case'saved':savedPage();break;case'login':loginPage();break;case'dashboard':dashboardPage();break;case'gallery':galleryPage();break;case'contact':contactPage();break;case'admin':adminPage();break;case'faq':faqPage();break;case'about':aboutPage();break;case'rooms':roomsPage();break;case'styles':stylePage();break;case'colours':coloursPage();break;case'flooring':flooringPage();break;case'lighting':lightingPage();break;case'doors':doorsPage();break;case'garden':gardenPage();break;case'construction':constructionPage();break;case'compare':comparePage();break;case'checklist':checklistPage();break;case'inspiration':inspirationPage();break;case'budgettips':budgetTips();break;case'profile':profilePage();break;case'materials':materialsPage();break;case'help':helpPage();break;case'wishlist':wishlistPage();break;case'report':reportPage();break;case'styleguide':styleGuidePage();break;case'maintenance':maintenancePage();break;case'terms':termsPage();break;default:home()}}
document.addEventListener('DOMContentLoaded',init);
